import { hsalsa } from '@noble/ciphers/salsa'
import { assert, assertUint8AnySize } from './assertUint8.mjs'
import { fromHex } from '@exodus/bytes/hex.js'
import { utf8fromString } from '@exodus/bytes/utf8.js'

// input: Uint8Array instance or a hex string
export function toUint8Array(input, size) {
  if (size !== undefined) {
    const result = toUint8Array(input) // convert without size and then re-check
    if (result.length !== size) throw new Error(`expected input of length ${size}`)
    return result
  }
  if (input instanceof Uint8Array) return input
  if (typeof input === 'string') return fromHex(input) // validates format
  throw new Error('expected Uint8Array, Buffer or hex string')
}

// input: Uint8Array instance or an unicode string
export function utf8Buf(input, size) {
  if (size !== undefined) {
    const result = utf8Buf(input) // convert without size and then re-check
    if (result.length !== size) throw new Error(`expected input of length ${size}`)
    return result
  }
  if (input instanceof Uint8Array) return input
  if (typeof input === 'string') return utf8fromString(input)
  throw new Error('expected Uint8Array, Buffer or a string')
}

export const salsaNonceBytes = 24
export const salsaKeyBytes = 32
export const salsaMacBytes = 16

const u32view = (arr) => {
  assertUint8AnySize(arr)
  assert(arr.byteLength % 4 === 0)
  return new Uint32Array(arr.buffer, arr.byteOffset, Math.floor(arr.byteLength / 4))
}

// Refs: https://github.com/paulmillr/noble-ciphers/issues/35
// Refs: https://github.com/jedisct1/libsodium/blob/master/src/libsodium/crypto_secretbox/crypto_secretbox_easy.c

const sigma32 = utf8fromString('expand 32-byte k')

export function salsaSharedSecret(sharedSecret) {
  const sigma = u32view(new Uint8Array(sigma32)) // clone just in case
  const out = new Uint8Array(32)
  hsalsa(sigma, u32view(sharedSecret), new Uint32Array(16), u32view(out))
  return out
}
